package com.example.sumapp;
import android.os.Bundle; import android.view.View; import android.widget.EditText; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity;
public class MainActivity extends AppCompatActivity { EditText etFirstNumber,etSecondNumber; TextView tvResult; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);etFirstNumber=findViewById(R.id.etFirstNumber);etSecondNumber=findViewById(R.id.etSecondNumber);tvResult=findViewById(R.id.tvResult);} String[] nums(){return new String[]{etFirstNumber.getText().toString().trim(),etSecondNumber.getText().toString().trim()};} public void performAddition(View v){calc("Addition Result : ",1);} public void performSubtraction(View v){calc("Subtraction Result : ",2);} public void performMultiplication(View v){calc("Multiplication Result : ",3);} public void performDivision(View v){String[] n=nums(); if(n[0].isEmpty()||n[1].isEmpty()){tvResult.setText("Please enter both numbers.");return;} double b=Double.parseDouble(n[1]); if(b==0){tvResult.setText("Division by zero is not allowed.");return;} tvResult.setText("Division Result : "+(Double.parseDouble(n[0])/b));} void calc(String label,int op){String[] n=nums();if(n[0].isEmpty()||n[1].isEmpty()){tvResult.setText("Please enter both numbers.");return;}int a=Integer.parseInt(n[0]),b=Integer.parseInt(n[1]);int r=op==1?a+b:op==2?a-b:a*b;tvResult.setText(label+r);}}
